<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Closure; use Illuminate\Support\Facades\Log; class InstallSteps { private const WAIT_SECONDS = 900; private const POLL_SECONDS = 3; private const SETTLED_POLLS = 3; public function run( ServerFiles $files, array $groups, string $fallbackJar = 'server.jar', ?Closure $progress = null, ): bool { $say = $progress ?? fn (string $message) => null; $groups = array_values(array_filter($groups, 'is_array')); $total = 0; foreach ($groups as $group) { $total += count($group); } $done = 0; foreach ($groups as $group) { foreach ($group as $step) { ++$done; $say("Step {$done} of {$total}."); if (!$this->step($files, is_array($step) ? $step : [], $fallbackJar, $say)) { return false; } } } return true; } private function step(ServerFiles $files, array $step, string $fallbackJar, Closure $say): bool { return match ((string) ($step['type'] ?? '')) { 'download' => $this->download($files, $step, $fallbackJar, $say), 'remove' => $this->remove($files, $step), 'unzip' => $this->unzip($files, $step), default => true, }; } private function download(ServerFiles $files, array $step, string $fallbackJar, Closure $say): bool { $url = (string) ($step['url'] ?? ''); $name = $this->safe((string) ($step['file'] ?? ''), $fallbackJar); if (!str_starts_with($url, 'https://') || $name === '') { return false; } $folder = dirname($name); $directory = $folder === '.' ? '/' : '/' . $folder; if ($directory !== '/') { $files->createDirectory($directory); } if (!$files->pullFile($directory, $url, basename($name))) { return false; } return $this->await($files, $directory, basename($name), (int) ($step['size'] ?? 0), $say); } private function await(ServerFiles $files, string $directory, string $name, int $expected, Closure $say): bool { $deadline = microtime(true) + self::WAIT_SECONDS; $previous = null; $settled = 0; do { sleep(self::POLL_SECONDS); $size = $files->entrySize($directory, $name); if ($size !== null && $size > 0) { if ($expected > 0 && $size >= $expected) { return true; } $settled = $size === $previous ? $settled + 1 : 0; if ($settled >= self::SETTLED_POLLS) { return true; } } $say( $expected > 0 && $size !== null && $size > 0 ? sprintf('Downloading %s - %d%%.', $name, min(99, (int) ($size / $expected * 100))) : "Downloading {$name}.", ); $previous = $size; } while (microtime(true) < $deadline); Log::warning('An install file never finished downloading', [ 'server' => $files->server->uuid, 'file' => $name, 'expected' => $expected, 'size' => $previous, ]); return false; } private function remove(ServerFiles $files, array $step): bool { $target = $this->safe((string) ($step['location'] ?? ''), ''); if ($target !== '') { $files->deletePaths('/', [$target]); } return true; } private function unzip(ServerFiles $files, array $step): bool { $file = $this->safe((string) ($step['file'] ?? ''), ''); $root = (string) ($step['location'] ?? '.'); $root = $root === '.' || $root === '' ? '/' : '/' . ltrim($root, '/'); return $file !== '' && $files->decompress($root, $file); } private function safe(string $name, string $fallback): string { $name = trim($name); return $name === '' || str_contains($name, '..') || str_starts_with($name, '/') ? $fallback : $name; } } 